<template><div class="space-y-3 p-4"><div><h1 class="text-xl font-bold text-slate-800">Payment ledger</h1><p class="mt-1 text-xs text-slate-400">PSP payment and settlement records</p></div><div v-for="item in items" :key="item.id" class="m-card"><div class="flex justify-between"><p class="text-xs font-semibold uppercase text-slate-500">{{ item.kind }}</p><span class="status-pill bg-indigo-50 text-indigo-600">{{ item.status }}</span></div><p class="mt-3 text-lg font-bold text-slate-800">{{ money(item.amount_minor, item.currency) }}</p><NuxtLink :to="`/buyer/orders/${item.order_id}`" class="mt-2 inline-block text-xs text-indigo-600">View order</NuxtLink></div><p v-if="error" class="m-card text-sm text-red-600">{{ error }}</p></div></template>
<script setup lang="ts">definePageMeta({ middleware: ['auth'] }); const { listPaymentLedger } = useCommerce(); const items = ref<any[]>([]); const error = ref(''); const money = (value: number, currency: string) => new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(value / 100); onMounted(async () => { try { items.value = (await listPaymentLedger()).items } catch (e: any) { error.value = e?.data?.detail || e?.message } })</script>
